from pathlib import Path
import ast,hashlib,json,subprocess
r=Path(__file__).resolve().parent;spec=json.loads((r/'spec.json').read_text());repo=Path(spec['repo']);head=spec['head_sha']
paths=['Source/WebCore/Modules/webaudio/'+n for n in ['AudioContext.cpp','AudioNodeOutput.cpp','MediaElementAudioSourceNode.cpp','BaseAudioContext.idl','AudioWorklet.idl','AudioWorkletNode.idl']]+['Source/WebCore/platform/audio/symbian/'+n for n in ['AudioDestinationSymbian.cpp','AudioDestinationSymbianNative.cpp','AudioFileReaderSymbian.cpp','FFTFrameSymbian.cpp']]+['Source/WebCore/page/Settings.yaml','Source/WebKitLegacy/symbian/WebViewImpl.cpp','Source/cmake/OptionsSymbian.cmake']
