assert all(checks.values()),checks
(r/'classic-source-verification.json').write_text(json.dumps({'status':'PASS_SOURCE_ONLY_ARTIFACT_PENDING','source_commit':head,'source_files':ids,'source_count':13,'checks':checks,'current_CI_image_executed':False,'local_C28_results_reused_as_CI_runtime':False},indent=2)+'\n')
extra=['Tools/Symbian/scripts/rebuild-sdk-complex.py','Tools/Symbian/scripts/rebuild-sdk-math.py','Tools/Symbian/patches/sdk-0.3.0/complex/manifest.json','Tools/Symbian/patches/sdk-0.3.0/math/manifest.json','Tools/Symbian/scripts/build-webcore.sh','Tools/Symbian/scripts/build-browser.sh','Tools/Symbian/tests/sdk-native-patch-stack/test_patch_stack.py']
for path in extra:
 data=subprocess.check_output(['git','show',head+':'+path],cwd=repo);p=r/'build-source'/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(data)
for p in r.glob('*.py'):ast.parse(p.read_text(),filename=str(p))
(r/'preparation-check.json').write_text(json.dumps({'status':'PASS_SOURCE_PREPARED','source_commit':head,'artifact_verification_pending':True,'auth_source_checks':11,'network_source_checks':25,'classic_source_checks':len(checks),'classic_runtime_source_snapshots':13,'native_patch_count':10,'native_verified_files':20,'default_WebAudio':'ON','no_guest_or_runtime_actions':True},indent=2)+'\n')
